/**
 * The parts the board showcase marks on each board (story.js draws them as dots over the stage image; pointing
 * at one, or tapping it, shows its card). Positions are fractions of the 1600x1200 stage image: each part's pad
 * centre in the board's own KiCad file, projected through the stills' camera (rotate -54,0,-26, perspective) by
 * a homography fitted to marker dots rendered with that camera, then cropped and scaled as the stage images were.
 * Generated by www-redesign/tools/hotparts.py (with markers.py and hotmap.py); the notes repeat the board facts
 * in data.ts and the parts' own values.
 */
export interface BoardPart {
  /** reference designator on the board */
  ref: string;
  /** the part, as its value in the KiCad file names it */
  name: string;
  /** what it does on this board */
  note: string;
  /** position on the stage image, 0-1 */
  x: number;
  y: number;
}

